m = ['src-metropolis-2001-labor','src-metropolis-2001-zones']
h = ['src-harlock-1978-machine-premise','src-harlock-earth-cargo']
R = [record('metropolis-2001-displaced-humans','c0533','Metropolis — human displacement under robot production','Metropolis','The 2001 film’s human population under plutocratic robot production',['anime','movie'],
 scope('2001 animated film','The established city order before the Ziggurat crisis','Living human city residents, including displaced poor citizens',['Robots as additional humans','The 1927 film','Tezuka’s manga as economically identical','The post-collapse order as already stable']),
 'Robot labor builds and maintains Metropolis, while many human residents lose jobs and live in degraded lower districts. Productive automation therefore coexists with severe insecurity rather than a shared leisure dividend. The weak guarantee estimate follows the actual contrast between concentrated wealth and displaced people’s squalor; it does not assume that every unemployed person receives no food at all. This is the existing automated-production order, not a promise that the later crisis creates equality.\n\nControl lies near the concentrated human end. Wealthy political actors, especially Duke Red, direct major projects and coercive institutions; robot workers and restricted movement do not themselves constitute an autonomous AI sovereign. Occupational segregation is visible, but it is not separately labeled a zero variant without proof of deliberate retention of replaceable human jobs. Detective work, informal activity, care and political organization remain useful human contributions. Job loss is not a census of all such work, so the nonworking axis stays open. The manga and earlier live-action film are excluded from these coordinates.',
 {'guarantees':0.85,'control':0.05,'nonworking':None},
 {'guarantees':assessment(0.85,[0.5,1],'medium','Actual robot-driven displacement and poor living conditions contrast with elite wealth; no broad secure floor is established.',m),
  'control':assessment(0.05,[0,0.2],'medium','Plutocratic human actors direct productive projects and robot enforcement, rather than an independently ruling AI.',m),
  'nonworking':assessment(None,None,'low','Mass unemployment is established, but useful unpaid work, age coverage and exact participation are not.',m)},
 3,m,[evidence('Robot construction and maintenance coexist with human unemployment, squalor and plutocratic power.',m,'Film plot opening and occupational-zone dialogue','secondary_film_reference_and_primary_dialogue')],
 ['An exclusionary automated-production comparison rather than guaranteed leisure.', 'Unemployment is distinct from total useful nonparticipation.', 'Robot zoning does not automatically create a separate zero variant.', 'The film is not merged with the manga or 1927 continuity.']),
 record('harlock-1978-leisured-earth','c0540','Captain Harlock — Earth’s machine-supported complacency','Space Pirate Captain Harlock','Ordinary human Earth society before the Mazone supply crisis',['anime'],
 scope('1978 television anime','Established Earth abundance before severe attacks on its food supply','Living human residents of Earth',['Offworld workers as known idle Earth residents','Harlock’s working crew as a representative census','Arcadia of My Youth or the 2013 film','Later crisis conditions as identical to the opening order']),
 'Earth’s ordinary society relies on machines for work and has settled into widespread leisure. The technological support is an established background to the story, not an unbuilt future proposal. Its material-guarantee estimate is moderately strong but uncertain: comfort depends on supply arrangements, including food carried from offworld farms. The checked references do not establish an unconditional legal entitlement or show that the planet can sustain itself after those routes are attacked.\n\nGovernment and elite institutions retain concentrated authority over the order, while individual leisure is not equivalent to productive ownership. Machine assistance and automated ships do not make every political decision an act of autonomous AI. A high nonworking estimate fits the explicit machine-work and general-indulgence premise, but remains a broad interpretation. Officials, scientists, transport crews and residents choosing useful care or creative work can still contribute. The outside farming and transport labor is disclosed rather than erased by the Earth-only denominator. Harlock’s exceptional crew and later emergency are separate from this ordinary opening society.',
 {'guarantees':-0.4,'control':0.05,'nonworking':0.9},
 {'guarantees':assessment(-0.4,[-0.8,0.35],'low','Established machine-supported abundance is real, but food imports and unverified universal access qualify security.',h),
  'control':assessment(0.05,[0,0.2],'medium','Human government/elite supply institutions remain decisive; ordinary leisure does not imply broad productive ownership.',h),
  'nonworking':assessment(0.9,[0.65,1],'low','The explicit machine-work and general-leisure premise supports a high noncanonical estimate, with room for real professional and voluntary work.',h)},
 1,h,[evidence('Opening Earth life is widely leisured under machine production, with food supplied through offworld transport.',h,'1978 series premise and Earth cargo-ship description','secondary_tv_synopsis_and_lore')],
 ['Television-only scope; related Matsumoto works have incompatible histories.', 'Offworld food production and transportation are not assumed labor-free.', 'Guarantees and participation are broad provisional estimates.', 'The later supply crisis is not hidden inside an unqualified abundance claim.'])]
D = [decision(cid,status,reason,['src-b70-'+sid],analysis=analysis,follow_up='Keep the concise gap/comparison and continue without whole-series or manga reconstruction.') for cid,sid,title,url,author,claim,status,reason,analysis in rows]
D += [decision('c0533','included','The film establishes robot production with actual human displacement under plutocratic control.',m,society_id='metropolis-2001-displaced-humans'),decision('c0540','included','The 1978 opening order has established machine-supported leisure, with food-import and scope limitations disclosed.',h,society_id='harlock-1978-leisured-earth')]
